def choose_move(observation):
    w, h = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    locations = {
        'resources': observation['resources'],
        'obstacles': observation['obstacles'],
        'opponent': observation['opponent_position']
    }

    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # Find closest resource
    target = None
    min_d = None
    for r in locations['resources']:
        d = dist(px, py, r[0], r[1])
        if min_d is None or d < min_d:
            min_d = d
            target = r

    # Find closest opponent
    opp = locations['opponent']
    opp_d = dist(px, py, opp[0], opp[1]) if opp else None

    # Decide whether to pursue resource or evade opponent
    if opp and opp_d and opp_d <= 2:
        # Evade opponent
        move_x = 0
        move_y = 0
        if opp[0] < px:
            move_x = 1
        elif opp[0] > px:
            move_x = -1
        if opp[1] < py:
            move_y = 1
        elif opp[1] > py:
            move_y = -1
        # Check obstacles
        new_x = px + move_x
        new_y = py + move_y
        if 0 <= new_x < w and 0 <= new_y < h and (new_x, new_y) not in observation['obstacles']:
            return [move_x, move_y]
        # Try alternative moves if blocked
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = px+dx, py+dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in observation['obstacles']:
                return [dx, dy]
        return [0,0]
    elif target:
        dx = dy = 0
        if target[0] > px:
            dx = 1
        elif target[0] < px:
            dx = -1
        if target[1] > py:
            dy = 1
        elif target[1] < py:
            dy = -1
        nx, ny = px + dx, py + dy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in observation['obstacles']:
